#!/usr/bin/env python3
"""Download immutable Core ML packages, verify every byte, then compile afresh.

Only source packages are cached. Compiled Core ML directories from earlier caches
are never trusted; they are regenerated by the runner's current Apple compiler.
Hashes of LFS files come from upstream SHA-256 LFS OIDs; JSON was downloaded and
hashed separately. Updating this lock is an explicit, reviewed code change.
"""
import argparse
import hashlib
import json
from pathlib import Path
import shutil
import subprocess
import tempfile
import time
import urllib.request


def valid_file(path, expected):
    if path.is_symlink() or not path.is_file() or path.stat().st_size != expected['size']:
        return False
    h = hashlib.sha256()
    with path.open('rb') as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b''):
            h.update(chunk)
    return h.hexdigest() == expected['sha256']


def download_verified(url, destination, expected):
    if valid_file(destination, expected):
        print('Verified cached package file:', destination.name)
        return
    destination.parent.mkdir(parents=True, exist_ok=True)
    for attempt in range(3):
        temporary = destination.with_name(destination.name + '.download')
        try:
            # Opening with wb truncates an old partial download. Never follow a cache symlink.
            if temporary.is_symlink():
                temporary.unlink()
            with urllib.request.urlopen(url, timeout=180) as response, temporary.open('wb') as f:
                shutil.copyfileobj(response, f, length=1024 * 1024)
            if not valid_file(temporary, expected):
                raise ValueError('Downloaded model file failed pinned size/SHA-256 verification')
            temporary.replace(destination)
            return
        except Exception:
            temporary.unlink(missing_ok=True)
            if attempt == 2:
                raise
            time.sleep(2 * (attempt + 1))


def compile_model(model, out):
    out.mkdir(parents=True, exist_ok=True)
    package_name = model['name'] + '.mlpackage'
    cache = out / '.verified-packages' / model['revision'] / package_name
    # Refuse paths redirected outside the selected output directory by a restored cache.
    if not cache.resolve().is_relative_to(out.resolve()):
        raise ValueError('Model cache redirects outside output directory')
    base = 'https://huggingface.co/' + model['repository'] + '/resolve/' + model['revision'] + '/' + package_name
    for name, expected in model['files'].items():
        destination = cache / name
        if not destination.parent.resolve().is_relative_to(out.resolve()):
            raise ValueError('Model cache file redirects outside output directory')
        download_verified(base + '/' + name, destination, expected)
    # Only allow pinned files in the compiler input. Ignore extra/untrusted cache contents.
    with tempfile.TemporaryDirectory(prefix='lumen-model-') as temporary:
        stage = Path(temporary)
        package = stage / package_name
        for name in model['files']:
            destination = package / name
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(cache / name, destination)
        compiled = stage / 'compiled'
        compiled.mkdir()
        subprocess.run(['xcrun', 'coremlcompiler', 'compile', str(package), str(compiled)], check=True)
        name = model['name'] + '.mlmodelc'
        generated = compiled / name
        if not generated.is_dir() or not any(generated.iterdir()):
            raise RuntimeError('Core ML compiler produced no model')
        target = out / name
        if target.is_symlink():
            target.unlink()
        elif target.exists():
            shutil.rmtree(target)
        shutil.copytree(generated, target)
    print('Compiled verified model:', model['name'], model['revision'])


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('model', choices=['depth', 'seg', 'heal'])
    parser.add_argument('output', type=Path)
    args = parser.parse_args()
    lock = json.loads(Path(__file__).with_name('model-lock.json').read_text())
    compile_model(lock['models'][args.model], args.output)
